CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, username text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('administrator','operator','viewer')), active boolean NOT NULL DEFAULT true);
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE settings(id integer PRIMARY KEY CHECK(id=1), timezone text NOT NULL DEFAULT 'Europe/Istanbul', minimum_shelf_days integer NOT NULL DEFAULT 0 CHECK(minimum_shelf_days BETWEEN 0 AND 3650), alert_days integer NOT NULL DEFAULT 30 CHECK(alert_days BETWEEN 0 AND 3650), last_alert_run timestamptz);
INSERT INTO settings(id) VALUES(1);
CREATE TABLE products(id uuid PRIMARY KEY, sku text UNIQUE NOT NULL CHECK(length(sku) BETWEEN 1 AND 80), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), category text NOT NULL DEFAULT 'General', barcode text UNIQUE, unit text NOT NULL DEFAULT 'each', whole_units boolean NOT NULL DEFAULT true, expiry_tracked boolean NOT NULL DEFAULT true, threshold numeric(18,3) NOT NULL DEFAULT 10 CHECK(threshold>=0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE batches(id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products, lot text NOT NULL, manufacture_date date, expiry_date date, supplier text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','quarantine','blocked','archived')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id,lot), CHECK(manufacture_date IS NULL OR expiry_date IS NULL OR manufacture_date<=expiry_date));
CREATE TABLE imports(id uuid PRIMARY KEY, kind text NOT NULL, rows jsonb NOT NULL, errors jsonb NOT NULL, actor uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), committed_at timestamptz);
CREATE TABLE movements(id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products, batch_id uuid NOT NULL REFERENCES batches, type text NOT NULL CHECK(type IN ('opening','receipt','issue','customer_return','supplier_return','write_off','adjustment','reversal')), requested numeric(18,3) NOT NULL CHECK(requested>0), effect numeric(18,3) NOT NULL CHECK(effect<>0), reference text NOT NULL DEFAULT '', reason text NOT NULL CHECK(length(reason)>0), actor uuid NOT NULL REFERENCES users, recorded_at timestamptz NOT NULL DEFAULT now(), source_issue uuid REFERENCES movements, reversal_of uuid UNIQUE REFERENCES movements, import_id uuid REFERENCES imports, CHECK(abs(effect)=requested));
CREATE INDEX movements_batch ON movements(batch_id);
CREATE INDEX movements_product ON movements(product_id);
CREATE TABLE commands(key text PRIMARY KEY, fingerprint text NOT NULL, actor uuid NOT NULL REFERENCES users, response jsonb NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit(id bigserial PRIMARY KEY, actor uuid REFERENCES users, action text NOT NULL, entity_id text NOT NULL, details jsonb NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE alerts(id uuid PRIMARY KEY, condition_key text UNIQUE NOT NULL, kind text NOT NULL, entity_id uuid NOT NULL, message text NOT NULL, state text NOT NULL CHECK(state IN ('open','acknowledged','resolved')), acknowledged_by uuid REFERENCES users, occurrences integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Posted ledger is immutable; use a compensating movement'; END $$;
CREATE TRIGGER immutable_movements BEFORE UPDATE OR DELETE ON movements FOR EACH ROW EXECUTE FUNCTION reject_ledger_mutation();
CREATE FUNCTION protect_product_units() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (OLD.unit<>NEW.unit OR OLD.whole_units<>NEW.whole_units OR OLD.expiry_tracked<>NEW.expiry_tracked) AND EXISTS(SELECT 1 FROM movements WHERE product_id=OLD.id) THEN RAISE EXCEPTION 'Established product unit, precision and expiry policy are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER product_units BEFORE UPDATE ON products FOR EACH ROW EXECUTE FUNCTION protect_product_units();
INSERT INTO schema_migrations(version) VALUES(1);
